"""Training task condicoes_pergunta (phase 7, DECISIONS D49), generated by code: no model, no network.

    .venv/bin/python tools/make_question_conditions.py generate [--out DIR]   training/data-v4/condicoes_pergunta/
                                                                             {train,held_out}.jsonl and INDEX.json

A question in the reader's prompt format, built from declared phrases; each phrase carries its typed condition (the
literal reading: a negation is ne / false, a list is in). 0 to 4 constraints per question, two non-reserved CCP
articles as context. The answer is {"condicoes": the stated constraints, in the question's order, and nothing else}.
Each constraint has train phrasings and held-out phrasings (held_out measures phrasings never seen). Excluded from both
splits: the constraint sets of the three B3 deadline questions and any question string equal to a B3 question.
"""
import argparse
import hashlib
import json
import random
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT)); sys.path.insert(0, str(ROOT / "tools"))
import make_training as mt  # noqa: E402
import read_rules  # noqa: E402  (the reader's vocabulary and the typed condition schema, D45)
from engine.canon import canonical, sha256_text  # noqa: E402

VERSION = "ccp-make-question-conditions-0.1"
DATA = ROOT / "training/data-v4"
TASK = "condicoes_pergunta"
FROZEN_AT = mt.FROZEN_AT
N_TRAIN, N_HELD = 4000, 400
SEED = 20261026
PROC = {"concurso_publico": "concurso público", "ajuste_direto": "ajuste direto", "consulta_previa": "consulta prévia",
        "concurso_limitado_previa_qualificacao": "concurso limitado por prévia qualificação", "procedimento_negociacao": "negociação",
        "dialogo_concorrencial": "diálogo concorrencial", "parceria_inovacao": "parceria para a inovação"}
# constraint kind -> (train phrasings, held-out phrasings); {x} is filled per value; each yields one typed condition
SLOTS = {
    "proc_eq": (["Num procedimento de {x}", "Para um procedimento de {x}"], ["Quando o procedimento adotado é o de {x}"]),
    "proc_ne": (["Num procedimento que não seja de {x}"], ["Fora do procedimento de {x}"]),
    "joue_true": (["cujo anúncio é publicado no Jornal Oficial da União Europeia", "com anúncio publicado no Jornal Oficial da União Europeia"],
                  ["publicitado também no Jornal Oficial da União Europeia"]),
    "joue_false": (["cujo anúncio não é publicado no Jornal Oficial da União Europeia", "sem anúncio no Jornal Oficial da União Europeia"],
                   ["não publicitado no Jornal Oficial da União Europeia"]),
    "obras_eq": (["para empreitada de obras públicas", "relativo a uma empreitada de obras públicas"], ["cujo objeto é uma empreitada de obras públicas"]),
    "obras_ne": (["para contrato que não é de empreitada", "para contrato que não seja de empreitada de obras públicas"], ["cujo contrato não é uma empreitada"]),
    "bens_eq": (["para aquisição de bens móveis"], ["destinado à compra de bens móveis"]),
    "servicos_eq": (["para aquisição de serviços"], ["destinado à contratação de serviços"]),
    "bens_servicos": (["para locação ou aquisição de bens móveis ou aquisição de serviços"], ["relativo a bens móveis ou a serviços"]),
    "acores": (["nos Açores"], ["na Região Autónoma dos Açores"]),
    "madeira": (["na Região Autónoma da Madeira"], ["na Madeira"]),
    "estado": (["promovido pelo Estado"], ["em que a entidade adjudicante é o Estado"]),
    "preco_lt": (["de valor inferior a {x} euros"], ["com preço base abaixo de {x} euros"]),
    "preco_ge": (["de valor igual ou superior a {x} euros"], ["com preço base de pelo menos {x} euros"]),
}
FIELD_OF = {"proc_eq": "tipo_procedimento", "proc_ne": "tipo_procedimento", "joue_true": "publicado_joue", "joue_false": "publicado_joue",
            "obras_eq": "tipo_contrato", "obras_ne": "tipo_contrato", "bens_eq": "tipo_contrato", "servicos_eq": "tipo_contrato",
            "bens_servicos": "tipo_contrato", "acores": "territorio", "madeira": "territorio", "estado": "tipo_entidade",
            "preco_lt": "preco_base", "preco_ge": "preco_base"}
THRESHOLDS = [5000, 20000, 30000, 75000, 150000, 221000, 750000, 1000000, 5538000]
TARGETS = ["qual é o prazo mínimo para apresentação das propostas", "qual é o limiar aplicável", "que regra se aplica",
           "que prazo vale para a apresentação das candidaturas", "que procedimento pode ser adotado"]
EXCLUDED_SETS = [  # the B3 deadline questions' constraint sets (D49): never taught, never held out
    {("tipo_procedimento", "eq", "concurso_publico"), ("publicado_joue", "eq", False), ("tipo_contrato", "ne", "obras")},
    {("tipo_procedimento", "eq", "concurso_publico"), ("publicado_joue", "eq", False), ("tipo_contrato", "eq", "obras")},
    {("tipo_procedimento", "eq", "concurso_publico"), ("publicado_joue", "eq", True)},
]
RULES_LINE = ("Regras: escolhe em «condicoes» só as condições que a pergunta enuncia, com estes campos e valores: "
              + "; ".join(f"{k}: {', '.join(json.dumps(v, ensure_ascii=False) for v in vals)}" for k, vals in read_rules.VOCAB.items())
              + "; preco_base: número em euros.")


def condition(kind, value):
    f = FIELD_OF[kind]
    if kind == "proc_eq": return {"field": f, "op": "eq", "value": value}
    if kind == "proc_ne": return {"field": f, "op": "ne", "value": value}
    if kind == "joue_true": return {"field": f, "op": "eq", "value": True}
    if kind == "joue_false": return {"field": f, "op": "eq", "value": False}
    if kind == "obras_eq": return {"field": f, "op": "eq", "value": "obras"}
    if kind == "obras_ne": return {"field": f, "op": "ne", "value": "obras"}
    if kind == "bens_eq": return {"field": f, "op": "eq", "value": "bens"}
    if kind == "servicos_eq": return {"field": f, "op": "eq", "value": "servicos"}
    if kind == "bens_servicos": return {"field": f, "op": "in", "value": ["bens", "servicos"]}
    if kind == "acores": return {"field": f, "op": "eq", "value": "PT-AC"}
    if kind == "madeira": return {"field": f, "op": "eq", "value": "PT-MA"}
    if kind == "estado": return {"field": f, "op": "eq", "value": "estado"}
    if kind == "preco_lt": return {"field": f, "op": "lt", "value": value}
    if kind == "preco_ge": return {"field": f, "op": "ge", "value": value}
    raise ValueError(kind)


def schema():
    return {"type": "object", "properties": {"condicoes": {"type": "array", "items": read_rules.typed_condition()}}, "required": ["condicoes"],
            "additionalProperties": False}


def one(rng, split):
    """A question with 0-4 constraints, one per field at most; its typed conditions in the question's order."""
    fields_used, parts, conds = set(), [], []
    k = rng.choice([0, 1, 1, 2, 2, 3, 3, 4])
    order = ["proc_eq", "proc_ne"] if rng.random() < 0.85 else []
    rest = [s for s in SLOTS if not s.startswith("proc")]
    rng.shuffle(rest)
    for kind in order[:1] + rest:
        if len(conds) >= k:
            break
        if kind.startswith("proc") and rng.random() < 0.15:
            kind = "proc_ne"
        f = FIELD_OF[kind]
        if f in fields_used:
            continue
        value = rng.choice(list(PROC)) if kind.startswith("proc") else (rng.choice(THRESHOLDS) if kind.startswith("preco") else None)
        phr = rng.choice(SLOTS[kind][0 if split == "train" else 1])
        x = PROC[value] if kind.startswith("proc") else (f"{value:,}".replace(",", " ") if kind.startswith("preco") else "")
        parts.append(phr.format(x=x))
        conds.append(condition(kind, value))
        fields_used.add(f)
    target = rng.choice(TARGETS)
    if parts and parts[0][0].isupper():
        question = f"{parts[0]}{', ' + ', '.join(parts[1:]) if len(parts) > 1 else ''}, {target}? Dê as condições."
    elif parts:
        question = f"Para um contrato {', '.join(parts)}, {target}? Dê as condições."
    else:
        question = f"Em geral, {target}? Dê as condições."
    return question, conds


def generate(store, held_doc):
    ctx = mt.Ctx(store, held_doc)
    b3_questions = {t["question"] for t in read_rules.TARGETS}
    pool = sorted(pid for pid, p in ctx.passages.items() if pid.startswith("ccp:art") and p["kind"] == "artigo" and not ctx.is_reserved(pid)
                  and mt.version_at(p, FROZEN_AT) and len(mt.version_at(p, FROZEN_AT)["text"]) <= 1200)
    files, index = {}, {"version": VERSION, "frozen_at": FROZEN_AT, "seed": SEED, "train_held_out_definition_sha256": held_doc.get("sha256"),
                        "split": {}, "files": {}, "excluded_sets": len(EXCLUDED_SETS)}
    sch = schema()
    seen = set()
    for split, n in (("train", N_TRAIN), ("held_out", N_HELD)):
        rng = random.Random(f"{SEED}|{split}")
        rows, guard = [], 0
        while len(rows) < n and guard < n * 20:
            guard += 1
            question, conds = one(rng, split)
            key = {(c["field"], c["op"], c["value"] if not isinstance(c["value"], list) else tuple(c["value"])) for c in conds}
            if question in b3_questions or any(key == s for s in EXCLUDED_SETS) or question in seen:
                continue
            seen.add(question)
            ctx_ids = rng.sample(pool, 2)
            prompt = mt.compose(RULES_LINE, FROZEN_AT, TASK, mt.candidate_block(ctx.passages, ctx_ids, FROZEN_AT), question)
            rows.append(json.dumps({"id": f"{TASK}:{sha256_text(prompt)[:16]}", "task": TASK, "prompt": prompt,
                                    "answer": json.dumps({"condicoes": conds}, ensure_ascii=False, separators=(",", ":")),
                                    "sources": ctx_ids, "schema": sch}, ensure_ascii=False))
        rel = f"{TASK}/{split}.jsonl"
        files[rel] = ("\n".join(rows) + "\n").encode("utf-8")
        index["split"][split] = len(rows)
    for rel in sorted(files):
        index["files"][rel] = {"sha256": hashlib.sha256(files[rel]).hexdigest(), "lines": files[rel].count(b"\n")}
    files["INDEX.json"] = (json.dumps(index, ensure_ascii=False, sort_keys=True, indent=1) + "\n").encode("utf-8")
    return files


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("cmd", choices=["generate"]); ap.add_argument("--out", default=str(DATA))
    a = ap.parse_args()
    store = mt.load_repo()
    held = json.loads(mt.HELD.read_text(encoding="utf-8"))
    files = generate(store, held)
    mt.write(files, Path(a.out))
    print(json.loads(files["INDEX.json"])["split"])


if __name__ == "__main__":
    main()
